4.4 3. Sizes and Ranges: Ask the Compiler

4.4.1 sizeof
#include &lt;stdio.h&gt;

int main(void) {
    printf("int    : %zu bytes\n", sizeof(int));
    printf("double : %zu bytes\n", sizeof(double));
    return 0;
}

Use %zu for sizeof results.



4.4.2 &lt;limits.h&gt;
#include &lt;limits.h&gt;

printf("%d .. %d\n", INT_MIN, INT_MAX);
printf("%u\n", UINT_MAX);

4.5 4. Declarations and Initialization
int count = 0;
//  │     │    │
//  │     │    └── initial value
//  │     └────── name
//  └──────────── type

⚠️ A declared-but-uninitialized local variable holds garbage. Always initialize: int x = 0;.


4.5.1 const
const double PI = 3.14159;
PI = 3.2;   // COMPILER ERROR

4.10 Worked Examples

4.10.1 Example 1 — Inspecting a type’s size and range
#include &lt;stdio.h&gt;
#include &lt;limits.h&gt;

int main(void) {
    printf("int  : %zu bytes, range %d .. %d\n",
           sizeof(int), INT_MIN, INT_MAX);
    printf("char : %zu byte,  range %d .. %d\n",
           sizeof(char), CHAR_MIN, CHAR_MAX);
    return 0;
}


4.10.2 Example 2 — The integer-division bug and its fix
int a = 7, b = 8, c = 10;
double avg = (a + b + c) / 3;   // BUG: integer division → 8.000000
double avg = (a + b + c) / 3.0; // FIX: floating-point → 8.333333


4.10.3 Example 3 — Evaluating a compound expression
int a = 1, b = 2, c = 3, d = 4, e = 0;
int result = a + b * c &gt; d && !e;
// Trace: b*c=6, a+6=7, !e=1, 7&gt;4=1, 1&&1=1  → result = 1

5.3 2. Floating-Point Arithmetic

5.3.1 Why it is approximate — the IEEE-754 model
float (32 bits):
[ sign : 1 bit ][ exponent : 8 bits ][ mantissa : 23 bits ]
Why 0.1 is not exact: 0.1 in binary repeats forever, like 1/3 in decimal. The machine stores the closest approximation.
printf("%.17f\n", 0.1 + 0.2);   // 0.30000000000000004


5.3.2 Comparing floating-point values
#include &lt;math.h&gt;

double a = 0.1 + 0.2, b = 0.3;
if (fabs(a - b) &lt; 1e-9) { /* "equal enough" */ }

Never write a == b for double. Use fabs(a - b) &lt; epsilon.

Default to double. float only when memory genuinely matters.

6.4 3. C++ Streams: cout and cin
#include &lt;iostream&gt;
using namespace std;

int main() {
    int n;  double x;
    cout &lt;&lt; "Enter n: ";  cin  &gt;&gt; n;
    cout &lt;&lt; "Enter x: ";  cin  &gt;&gt; x;
    cout &lt;&lt; "n=" &lt;&lt; n &lt;&lt; "  x=" &lt;&lt; x &lt;&lt; "\n";
    return 0;
}

No format specifier, no & — types resolved at compile time.
cin &gt;&gt; skips leading whitespace automatically.


6.4.1 Formatting with &lt;iomanip&gt;
#include &lt;iomanip&gt;

cout &lt;&lt; fixed &lt;&lt; setprecision(2) &lt;&lt; 3.14159 &lt;&lt; "\n";  // 3.14
cout &lt;&lt; setw(10) &lt;&lt; 42 &lt;&lt; "\n";                        //         42

fixed + setprecision(n) — persist for the stream’s lifetime.
setw(n) — applies to the next item only.

6.6 5. Structured Linear Programs
/* READ */
scanf(...);

/* COMPUTE */
double result = ...;

/* WRITE */
printf(...);
Separating the phases makes programs easy to read, test, and extend.

6.9 Worked Examples

6.9.1 Example 1 — Formatted receipt
printf("%-15s %8s\n",   "Item",    "Price");
printf("%-15s %8.2f\n", "Coffee",  2.50);
printf("%-15s %8.2f\n", "Sandwich",5.99);
printf("%-15s %8.2f\n", "TOTAL",   8.49);


6.9.2 Example 2 — Input with validation
int a, b;
printf("Enter two integers: ");
if (scanf("%d %d", &a, &b) != 2) {
    printf("Error: expected 2 integers\n");
    return 1;
}
printf("Sum = %d\n", a + b);


6.9.3 Example 3 — C++ formatted output
double radius;
cin &gt;&gt; radius;
const double PI = 3.14159265358979;
cout &lt;&lt; fixed &lt;&lt; setprecision(4);
cout &lt;&lt; "Area: " &lt;&lt; setw(12) &lt;&lt; PI * radius * radius &lt;&lt; "\n";

7.2 1. The if Statement

7.2.1 if/else
if (condition) {
    /* runs when condition is true (non-zero) */
} else {
    /* runs when condition is false (zero) */
}
Always use braces, even for a single statement.


7.2.2 if/else if/else
if (score &gt;= 90) {
    printf("Grade: A\n");
} else if (score &gt;= 80) {
    printf("Grade: B\n");
} else if (score &gt;= 70) {
    printf("Grade: C\n");
} else {
    printf("Grade: F\n");
}
Conditions checked top to bottom; first true branch runs.


7.2.3 The dangling else trap
In C, else always attaches to the nearest preceding unmatched if, regardless of indentation. Fix: always use braces.

7.3 2. The switch Statement
switch (expression) {
    case value1:
        /* statements */
        break;
    case value2:
        /* statements */
        break;
    default:
        /* runs when no case matches */
}

expression must be an integer or character — no floats or strings.
break is required to exit the switch.
Fall-through — intentional grouping:

switch (day) {
    case 1: case 2: case 3: case 4: case 5:
        printf("Weekday\n");
        break;
    case 6: case 7:
        printf("Weekend\n");
        break;
}

7.4 3. The for Loop
for (initialization; condition; update) {
    /* loop body */
}
for (int i = 1; i &lt;= 10; i++) {
    printf("%d\n", i);
}

7.4.1 The off-by-one trap
for (int i = 0; i &lt; 10; i++)  { }  /* 10 iterations: 0..9  — correct */
for (int i = 0; i &lt;= 10; i++) { }  /* 11 iterations — usually a bug */

7.5 4. The while Loop
while (condition) {
    /* loop body */
}
Condition checked before every iteration. If false initially, body never runs.
Sentinel-controlled loop:
int value, sum = 0;
while (scanf("%d", &value) == 1 && value != -1) {
    sum += value;
}

7.6 5. The do-while Loop
do {
    /* loop body — runs at least once */
} while (condition);
int choice;
do {
    printf("1) New game  2) Load  3) Quit\nYour choice: ");
    scanf("%d", &choice);
} while (choice &lt; 1 || choice &gt; 3);

7.7 6. break and continue
for (int i = 0; i &lt; 10; i++) {
    if (i == 5) break;       /* exit loop — prints 0..4 */
    printf("%d\n", i);
}

for (int i = 0; i &lt; 10; i++) {
    if (i % 2 == 0) continue; /* skip even — prints 1,3,5,7,9 */
    printf("%d\n", i);
}
Both affect only the innermost enclosing loop.

7.9 Common Patterns
Accumulator:
int sum = 0;
for (int i = 1; i &lt;= n; i++) sum += i;
Min / max (initialise from first element):
int min = a[0], max = a[0];
for (int i = 1; i &lt; n; i++) {
    if (a[i] &lt; min) min = a[i];
    if (a[i] &gt; max) max = a[i];
}
Input validation:
int age;
do {
    printf("Enter age (1–120): ");
    scanf("%d", &age);
} while (age &lt; 1 || age &gt; 120);

7.12 Worked Examples

7.12.1 Example 1 — Classify a triangle
double a, b, c;
scanf("%lf %lf %lf", &a, &b, &c);

if (a + b &lt;= c || a + c &lt;= b || b + c &lt;= a) {
    printf("Not a valid triangle.\n");
} else if (a == b && b == c) {
    printf("Equilateral triangle.\n");
} else if (a == b || b == c || a == c) {
    printf("Isosceles triangle.\n");
} else {
    printf("Scalene triangle.\n");
}


7.12.2 Example 2 — Sum and average with while
double value, sum = 0.0;
int count = 0;
printf("Enter numbers (0 to stop):\n");
scanf("%lf", &value);
while (value != 0.0) {
    sum += value;
    count++;
    scanf("%lf", &value);
}
if (count &gt; 0)
    printf("Average: %.2f\n", sum / count);


7.12.3 Example 3 — FizzBuzz
for (int i = 1; i &lt;= 20; i++) {
    if      (i % 15 == 0) printf("FizzBuzz\n");
    else if (i % 3  == 0) printf("Fizz\n");
    else if (i % 5  == 0) printf("Buzz\n");
    else                   printf("%d\n", i);
}

8.4 4. Core Processing Patterns
Sum and average:
int sum = 0;
for (int i = 0; i &lt; n; i++) sum += arr[i];
double avg = (double)sum / n;
Maximum (initialize from first element):
int max = arr[0];
for (int i = 1; i &lt; n; i++)
    if (arr[i] &gt; max) max = arr[i];

Initialize from arr[0], not 0 — if all values are negative, 0 would be wrong.

Linear search:
int found = -1;
for (int i = 0; i &lt; n; i++)
    if (arr[i] == target) { found = i; break; }

8.7 7. Arrays as Function Parameters
Arrays decay to pointers when passed to functions — the function gets the address of the first element, not a copy.
void print_array(int *arr, int n) {
    for (int i = 0; i &lt; n; i++) printf("%d ", arr[i]);
    printf("\n");
}

void scale_array(int *arr, int n, int factor) {
    for (int i = 0; i &lt; n; i++) arr[i] *= factor;   // modifies original!
}

⚠️ sizeof(arr) inside a function gives the pointer size (8 bytes), not the array size. Always pass n explicitly.

To prevent modification: void print_array(const int *arr, int n);

8.9 Worked Examples

8.9.1 Example 1: Grade Statistics
#define N 5
int grades[N] = {85, 92, 78, 95, 88};
int sum = 0, max = grades[0], min = grades[0];

for (int i = 0; i &lt; N; i++) {
    sum += grades[i];
    if (grades[i] &gt; max) max = grades[i];
    if (grades[i] &lt; min) min = grades[i];
}

printf("Average: %.1f\n", (double)sum / N);
printf("Max: %d  Min: %d\n", max, min);


8.9.2 Example 2: Reverse an Array In Place
void reverse(int *arr, int n) {
    for (int i = 0; i &lt; n / 2; i++) {
        int tmp = arr[i];
        arr[i] = arr[n - 1 - i];
        arr[n - 1 - i] = tmp;
    }
}


8.9.3 Example 3: Pointer Arithmetic Trace
int a[3] = {10, 20, 30};
int *p = a;
printf("%d\n", *(p + 0));   // 10
printf("%d\n", *(p + 1));   // 20
printf("%d\n", *(p + 2));   // 30

9.7 6. std::string in C++
#include &lt;string&gt;
using namespace std;

string s = "Hello";
s += ", world!";
cout &lt;&lt; s &lt;&lt; "\n";          // Hello, world!
cout &lt;&lt; s.length() &lt;&lt; "\n"; // 13
Key operations:
s.length()             // character count (= s.size())
s.empty()              // true if length == 0
s.substr(0, 5)         // "Hello"
s.find("world")        // index, or string::npos if absent
s.compare(t)           // 0 if equal
const char *c = s.c_str();  // interop with C functions
No null terminator to manage. No buffer overflow. Use std::string in new C++ code.

9.10 Worked Examples

9.10.1 Example 1 — String Reversal In Place
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

void reverse_string(char *s) {
    int left = 0, right = (int)strlen(s) - 1;
    while (left &lt; right) {
        char tmp = s[left];
        s[left]  = s[right];
        s[right] = tmp;
        left++; right--;
    }
}

int main(void) {
    char word[] = "race";
    printf("Before: %s\n", word);   // race
    reverse_string(word);
    printf("After:  %s\n", word);   // ecar
    return 0;
}


9.10.2 Example 2 — Counting Vowels
int count_vowels(const char *s) {
    int count = 0;
    const char *vowels = "aeiouAEIOU";
    for (int i = 0; s[i] != '\0'; i++)
        if (strchr(vowels, s[i]) != NULL)
            count++;
    return count;
}


9.10.3 Example 3 — Safe Input + Validation
char name[50];
printf("Enter your name: ");
fgets(name, sizeof(name), stdin);
name[strcspn(name, "\n")] = '\0';

if (strlen(name) == 0) {
    printf("Error: name cannot be empty.\n");
    return 1;
}
printf("Hello, %s! (%zu chars)\n", name, strlen(name));

11.2 2. Defining and Calling a Function

11.2.1 Anatomy
int cube(int n) {
    return n * n * n;
}







Part
Meaning




int (before name)
return type — the type of value the function sends back


cube
function name


int n
parameter — a local copy of the caller’s argument


return n * n * n;
compute and hand the result back





11.2.2 Prototype (declaration)
When the definition appears after main, declare a prototype above it:
int cube(int n);        /* prototype */

int main(void) {
    printf("%d\n", cube(4));
    return 0;
}

int cube(int n) {       /* definition */
    return n * n * n;
}


11.2.3 void — no return value
void print_greeting(char *name) {
    printf("Hello, %s!\n", name);
}

11.3 3. Parameters and Return Values

11.3.1 Pass by value
C copies the argument into the parameter. The original is never changed:
void double_it(int x) {
    x = x * 2;   /* only the local copy changes */
}

int main(void) {
    int a = 5;
    double_it(a);
    printf("%d\n", a);   /* still 5 */
}
x inside double_it is a separate memory location from a in main.


11.3.2 Early return
int max(int a, int b) {
    if (a &gt; b) return a;
    return b;
}

11.6 6. Recursion
A recursive function calls itself. Two mandatory parts:

Base case — returns without a self-call (stops the chain)
Recursive case — calls itself on a strictly smaller input


11.6.1 6.1 Factorial
int factorial(int n) {
    if (n == 0) return 1;            /* base case */
    return n * factorial(n - 1);    /* recursive case */
}
Trace: factorial(4) → 4 * factorial(3) → … → 4 * 3 * 2 * 1 * 1 = 24


11.6.2 6.2 Fibonacci
int fib(int n) {
    if (n &lt;= 1) return n;            /* base case */
    return fib(n - 1) + fib(n - 2); /* recursive case */
}

Caution: fib(40) makes ~2 billion calls — exponential time O(2^n). A loop version is O(n).



11.6.3 6.3 Binary search (recursive)
int binary_search(int arr[], int low, int high, int target) {
    if (low &gt; high) return -1;                    /* base case: not found */
    int mid = low + (high - low) / 2;
    if (arr[mid] == target) return mid;           /* base case: found */
    if (arr[mid] &lt; target)
        return binary_search(arr, mid + 1, high, target);
    return binary_search(arr, low, mid - 1, target);
}
Each call halves the search space → O(log n).

11.7 Worked Examples

11.7.1 Example 1 — Custom string length
#include &lt;stdio.h&gt;

int my_strlen(const char *s) {
    int count = 0;
    while (s[count] != '\0') count++;
    return count;
}

int main(void) {
    char word[] = "Hello";
    printf("Length = %d\n", my_strlen(word));  /* 5 */
    return 0;
}
This is the inline logic from L07 — now packaged as a reusable, named function.


11.7.2 Example 2 — Power: iterative vs recursive
double power_iter(double base, int exp) {
    double r = 1.0;
    for (int i = 0; i &lt; exp; i++) r *= base;
    return r;
}

double power_rec(double base, int exp) {
    if (exp == 0) return 1.0;
    return base * power_rec(base, exp - 1);
}


11.7.3 Example 3 — Count digits (recursive)
int count_digits(int n) {
    if (n &lt; 0) n = -n;
    if (n &lt; 10) return 1;              /* base case */
    return 1 + count_digits(n / 10);  /* strip last digit */
}

12.2 2. Opening and Closing Files
#include &lt;stdio.h&gt;

FILE *fp = fopen("filename.txt", "mode");
if (fp == NULL) {
    perror("fopen");
    return 1;
}
// ... use file ...
fclose(fp);
Common modes:



Mode
Effect




"r"
Read — file must exist


"w"
Write — creates/truncates


"a"
Append


"rb" / "wb"
Binary equivalents



Rule: Always check fopen for NULL. Always call fclose. Forgetting fclose can cause data loss (buffered writes not flushed to disk).

12.3 3. Text File I/O

12.3.1 Writing
fprintf(fp, "Score: %d\n", 95);
fputs("Done.\n", fp);


12.3.2 Reading — fgets (preferred)
char line[256];
while (fgets(line, sizeof(line), fp) != NULL) {
    printf("%s", line);
}


12.3.3 The feof trap
// WRONG — processes one extra iteration after EOF
while (!feof(fp)) { fgets(line, sizeof(line), fp); ... }

// CORRECT — test the return value of the read
while (fgets(line, sizeof(line), fp) != NULL) { ... }
feof is only set after a failed read — using it as the loop condition causes an extra empty iteration.

12.4 4. Binary File I/O
typedef struct { int id; char name[32]; float gpa; } Student;

// Write
FILE *fp = fopen("students.bin", "wb");
if (!fp) { perror("fopen"); return 1; }
fwrite(db, sizeof(Student), count, fp);
fclose(fp);

// Read
Student s;
fp = fopen("students.bin", "rb");
if (!fp) { perror("fopen"); return 1; }
while (fread(&s, sizeof(Student), 1, fp) == 1)
    printf("[%d] %s — GPA %.2f\n", s.id, s.name, s.gpa);
fclose(fp);
Use "wb"/"rb" modes — on Windows, text-mode translation corrupts binary data.

12.4.1 Random access
fseek(fp, N * sizeof(Student), SEEK_SET);  // jump to record N
long pos = ftell(fp);                       // current byte offset
rewind(fp);                                 // back to beginning

12.5 5. Error Handling
#include &lt;errno.h&gt;
#include &lt;string.h&gt;

FILE *fp = fopen("missing.txt", "r");
if (!fp) {
    perror("fopen");            // prints: "fopen: No such file or directory"
    // or: printf("%s\n", strerror(errno));
    return 1;
}
if (ferror(fp)) {
    perror("I/O error");
    clearerr(fp);
}
Standard pattern: open → check NULL → read/write → check ferror → close.

12.6 6. The Discipline and C++ Streams

12.6.1 Three rules

If you fopen, you fclose — in all code paths.
Check every fopen for NULL.
Check fread/fwrite return values.



12.6.2 fflush — flush without closing
fprintf(fp, "Step done.\n");
fflush(fp);   // data committed to disk immediately


12.6.3 C++ streams (RAII — auto-close)
#include &lt;fstream&gt;
#include &lt;string&gt;

std::ofstream out("output.txt");
out &lt;&lt; "Score: " &lt;&lt; 95 &lt;&lt; "\n";
// closes automatically when out goes out of scope

std::ifstream in("data.txt");
std::string line;
while (std::getline(in, line))
    std::cout &lt;&lt; line &lt;&lt; "\n";
C++ streams are type-safe and auto-close via RAII — the destructor calls close() when the stream object goes out of scope, preventing resource leaks.

12.7 Worked Examples

12.7.1 Example 1 — Word/line/character counter
#include &lt;stdio.h&gt;
#include &lt;ctype.h&gt;

int main(void) {
    FILE *fp = fopen("essay.txt", "r");
    if (!fp) { perror("fopen"); return 1; }

    long chars = 0, words = 0, lines = 0;
    int in_word = 0, c;

    while ((c = fgetc(fp)) != EOF) {
        chars++;
        if (c == '\n') lines++;
        if (isspace(c)) { in_word = 0; }
        else { if (!in_word) { words++; in_word = 1; } }
    }

    if (ferror(fp)) perror("read");
    fclose(fp);
    printf("Lines: %ld  Words: %ld  Chars: %ld\n", lines, words, chars);
    return 0;
}
Note: c must be int to correctly detect EOF = -1.


12.7.2 Example 2 — Binary student records
#include &lt;stdio.h&gt;
typedef struct { int id; char name[32]; float gpa; } Student;

int main(void) {
    Student db[] = {{1,"Alice",3.9f},{2,"Bob",3.4f},{3,"Carol",3.7f}};

    FILE *fp = fopen("students.bin", "wb");
    if (!fp) { perror("fopen"); return 1; }
    fwrite(db, sizeof(Student), 3, fp);
    fclose(fp);

    Student s;
    fp = fopen("students.bin", "rb");
    if (!fp) { perror("fopen"); return 1; }
    while (fread(&s, sizeof(Student), 1, fp) == 1)
        printf("[%d] %s — GPA %.2f\n", s.id, s.name, s.gpa);
    fclose(fp);
    return 0;
}


12.7.3 Example 3 — Binary file copy
#include &lt;stdio.h&gt;
#define BUF 4096

int main(void) {
    FILE *in  = fopen("source.jpg", "rb");
    if (!in)  { perror("source"); return 1; }
    FILE *out = fopen("backup.jpg", "wb");
    if (!out) { perror("dest"); fclose(in); return 1; }

    unsigned char buf[BUF];
    size_t n;
    while ((n = fread(buf, 1, BUF, in)) &gt; 0)
        fwrite(buf, 1, n, out);

    fclose(in);
    fclose(out);
    return 0;
}

13.2 2. malloc and calloc
#include &lt;stdlib.h&gt;

void *malloc(size_t size);                 /* uninitialized */
void *calloc(size_t nmemb, size_t size);   /* zero-initialized */
malloc — uninitialized allocation:
int    *arr    = malloc(n * sizeof(int));
double *grades = malloc(n * sizeof(double));
calloc — zero-initialized allocation:
double *grades = calloc(n, sizeof(double));   /* all 0.0 */
int    *flags  = calloc(n, sizeof(int));      /* all 0 */
Always use sizeof(type) — never hardcode byte sizes.

13.3 3. The NULL Guard (mandatory)
malloc and calloc return NULL on failure. Always check:
int *arr = malloc(n * sizeof(int));
if (arr == NULL) {
    fprintf(stderr, "Allocation failed\n");
    exit(EXIT_FAILURE);
}
Never skip this check — dereferencing NULL causes a crash or silent heap corruption.

13.4 4. realloc — Resizing
void *realloc(void *ptr, size_t new_size);
Safe pattern:
int *tmp = realloc(arr, capacity * sizeof(int));
if (tmp == NULL) {
    free(arr);
    exit(EXIT_FAILURE);
}
arr = tmp;
Never:
arr = realloc(arr, ...);    /* if it fails: arr = NULL, old block leaked */

13.5 5. free — Returning Memory
void free(void *ptr);   /* free(NULL) is safe — no-op */
After every free, set the pointer to NULL:
free(arr);
arr = NULL;
Three rules: 1. Every malloc/calloc has exactly one free. 2. Only free heap pointers. 3. Set to NULL after freeing.

13.8 8. Worked Examples

13.8.1 Example 1 — Dynamic Grade Array
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main(void) {
    int n;
    printf("Number of students: ");
    scanf("%d", &n);
    if (n &lt;= 0) { fprintf(stderr, "Invalid\n"); return EXIT_FAILURE; }

    double *grades = calloc(n, sizeof(double));
    if (!grades) { fprintf(stderr, "Allocation failed\n"); return EXIT_FAILURE; }

    for (int i = 0; i &lt; n; i++) {
        printf("Grade %d: ", i + 1);
        scanf("%lf", &grades[i]);
    }

    double sum = 0.0;
    for (int i = 0; i &lt; n; i++) sum += grades[i];
    printf("Average: %.2f\n", sum / n);

    free(grades);
    grades = NULL;
    return 0;
}


13.8.2 Example 2 — Growing Buffer with realloc
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main(void) {
    int capacity = 4, count = 0;
    int *arr = malloc(capacity * sizeof(int));
    if (!arr) { exit(EXIT_FAILURE); }

    int value;
    while (1) {
        printf("Enter integer (-1 to stop): ");
        if (scanf("%d", &value) != 1 || value == -1) break;

        if (count == capacity) {
            capacity *= 2;
            int *tmp = realloc(arr, capacity * sizeof(int));
            if (!tmp) { free(arr); exit(EXIT_FAILURE); }
            arr = tmp;
        }
        arr[count++] = value;
    }

    printf("Stored %d numbers:", count);
    for (int i = 0; i &lt; count; i++) printf(" %d", arr[i]);
    printf("\n");

    free(arr);
    arr = NULL;
    return 0;
}


