14.6 Condition Variables — Producer–Consumer
#include &lt;condition_variable&gt;
#include &lt;queue&gt;

std::queue&lt;int&gt;         buffer;
std::mutex              mtx;
std::condition_variable cv;
const int               MAX = 5;

void producer() {
    for (int i = 0; i &lt; 10; i++) {
        std::unique_lock&lt;std::mutex&gt; lk(mtx);
        cv.wait(lk, []{ return buffer.size() &lt; MAX; });
        buffer.push(i);
        cv.notify_one();
    }
}

void consumer() {
    for (int i = 0; i &lt; 10; i++) {
        std::unique_lock&lt;std::mutex&gt; lk(mtx);
        cv.wait(lk, []{ return !buffer.empty(); });
        int v = buffer.front(); buffer.pop();
        cv.notify_one();
    }
}
cv.wait(lock, predicate) releases the lock and sleeps. On wakeup, re-checks predicate — protects against spurious wakeups.

